class RunningMean:
    def __init__(self):
        self.total, self.count = 0.0, 0
    def update(self, value):
        self.total += value
        self.count += 1
    def value(self):
        if self.count == 0:
            raise ValueError("Mean is undefined before any updates")
        return self.total / self.count

class Affine(torch.nn.Module):
    def __init__(self, d_in, d_out):
        super().__init__()
        self.weight = torch.nn.Parameter(torch.randn(d_in, d_out) * 0.02)
        self.bias = torch.nn.Parameter(torch.zeros(d_out))
    def forward(self, x):
        return x @ self.weight + self.bias
